package edu.casestudy.merkle.service;
import edu.casestudy.merkle.core.*; import edu.casestudy.merkle.data.*; import edu.casestudy.merkle.data.Entities.*; import edu.casestudy.merkle.data.Repositories.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.stream.*;
@Service public class IntegrityService { final Datasets datasets;final Records records;final Checkpoints checkpoints;final Verifications verifications;final Audits audits; public IntegrityService(Datasets d,Records r,Checkpoints c,Verifications v,Audits a){datasets=d;records=r;checkpoints=c;verifications=v;audits=a;}
 public MerkleTree tree(UUID id){return new MerkleTree(records.findByDatasetIdOrderByPosition(id).stream().map(r->new MerkleTree.Leaf(r.id,r.position,r.payload)).toList());} public Dataset dataset(UUID id){return datasets.findById(id).orElseThrow(()->new NoSuchElementException("Dataset not found"));} public void audit(UUID id,String type,String details){var a=new Audit();a.datasetId=id;a.type=type;a.details=details;audits.save(a);}
 @Transactional public Dataset create(String name){var d=new Dataset();d.name=name.trim();datasets.save(d);audit(d.id,"DATASET_CREATED",d.name);return d;} @Transactional public Dataset rename(UUID id,String name){var d=dataset(id);d.name=name.trim();d.updatedAt=java.time.Instant.now();datasets.save(d);audit(id,"DATASET_RENAMED",d.name);return d;} @Transactional public DatasetRecord add(UUID did,String payload){dataset(did);var r=new DatasetRecord();r.datasetId=did;r.position=records.findByDatasetIdOrderByPosition(did).size();r.payload=payload;records.save(r);bump(did);audit(did,"RECORD_ADDED",r.id.toString());return r;} @Transactional public DatasetRecord update(UUID did,UUID rid,String payload){var r=records.findById(rid).orElseThrow();if(!r.datasetId.equals(did))throw new NoSuchElementException();r.payload=payload;r.updatedAt=java.time.Instant.now();records.save(r);bump(did);audit(did,"RECORD_UPDATED",rid.toString());return r;} @Transactional public void delete(UUID did,UUID rid){var r=records.findById(rid).orElseThrow();if(!r.datasetId.equals(did))throw new NoSuchElementException();records.delete(r);bump(did);audit(did,"RECORD_DELETED",rid.toString());} void bump(UUID id){var d=dataset(id);d.version++;d.updatedAt=java.time.Instant.now();datasets.save(d);}
 public Map<String,Object> verify(UUID id){var d=dataset(id);var t=tree(id);var cp=checkpoints.findByDatasetIdOrderByCreatedAtDesc(id).stream().findFirst();var changed=new ArrayList<String>();var findings=new ArrayList<Map<String,String>>();String status="UNVERIFIED";if(cp.isPresent()){Map<String,String> old=parse(cp.get().manifest);Map<String,String> now=manifest(t,id);for(var e:now.entrySet())if(!Objects.equals(old.get(e.getKey()),e.getValue())){changed.add(e.getKey());findings.add(Map.of("recordId",e.getKey(),"kind",old.containsKey(e.getKey())?"MODIFIED":"INSERTED","currentHash",e.getValue(),"expectedHash",old.getOrDefault(e.getKey(),"")));}for(String key:old.keySet())if(!now.containsKey(key)){changed.add(key);findings.add(Map.of("recordId",key,"kind","DELETED","currentHash","","expectedHash",old.get(key)));}status=cp.get().rootHash.equals(t.root())?"VERIFIED":"FAILED";}var v=new Verification();v.datasetId=id;v.datasetVersion=d.version;v.status=status;v.details=String.join(",",changed);verifications.save(v);audit(id,"VERIFICATION_"+status,"root="+t.root());var out=new LinkedHashMap<String,Object>();out.put("status",status);out.put("currentRoot",t.root());out.put("trustedRoot",cp.map(x->x.rootHash).orElse(null));out.put("affectedRecordIds",changed);out.put("findings",findings);out.put("at",v.createdAt.toString());return out;}
 public Map<String,String> manifest(MerkleTree t,UUID id){return records.findByDatasetIdOrderByPosition(id).stream().collect(Collectors.toMap(r->r.id.toString(),r->HashUtils.hex(HashUtils.leaf(RecordCanonicalizer.canonical(r.id,r.position,r.payload)))));} public String encode(Map<String,String> x){return x.entrySet().stream().map(e->e.getKey()+":"+e.getValue()).collect(Collectors.joining("\n"));}public Map<String,String> parse(String s){return Arrays.stream(s.split("\n")).filter(x->x.contains(":" )).map(x->x.split(":",2)).collect(Collectors.toMap(x->x[0],x->x[1]));}}
